fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();
    
    // Create the first output matrix filled with values from x
    let mut x_grid = vec![vec![0.0; cols]; rows];
    for i in 0..rows {
        for j in 0..cols {
            x_grid[i][j] = x[j];
        }
    }
    
    // Create the second output matrix filled with values from y
    let mut y_grid = vec![vec![0.0; cols]; rows];
    for i in 0..rows {
        for j in 0..cols {
            y_grid[i][j] = y[i];
        }
    }
    
    (x_grid, y_grid)
}